/* the coupon's devices other than the descriptor EEPROM */
struct coupon_desc_device {
	uint16_t part; /* 0x00: enum coupon_part; 0 = empty entry */
	uint8_t bus; /* 0x02: enum coupon_bus */
	uint8_t addr; /* 0x03: I2C: 7-bit address; SPI: select line (0 CS0_N, 1 CS1_N, 2-7 G0-G5); analog: lane mask */
	uint8_t count; /* 0x04: identical devices behind this entry (address-selected, or sensors on lanes) */
	uint8_t irq; /* 0x05: enum coupon_irq */
	uint8_t flags; /* 0x06: COUPON_DEV_F_* bits */
	uint8_t spi_mode; /* 0x07: SPI mode 0-3 (CPOL, CPHA) for an SPI device; 0 otherwise */
} __attribute__((packed));
_Static_assert(sizeof(struct coupon_desc_device) == 8, "coupon_desc_device size");
_Static_assert(offsetof(struct coupon_desc_device, part) == 0x00, "coupon_desc_device.part");
_Static_assert(offsetof(struct coupon_desc_device, bus) == 0x02, "coupon_desc_device.bus");
_Static_assert(offsetof(struct coupon_desc_device, addr) == 0x03, "coupon_desc_device.addr");
_Static_assert(offsetof(struct coupon_desc_device, count) == 0x04, "coupon_desc_device.count");
_Static_assert(offsetof(struct coupon_desc_device, irq) == 0x05, "coupon_desc_device.irq");
_Static_assert(offsetof(struct coupon_desc_device, flags) == 0x06, "coupon_desc_device.flags");
_Static_assert(offsetof(struct coupon_desc_device, spi_mode) == 0x07, "coupon_desc_device.spi_mode");

/* the whole descriptor, 256 bytes */
struct coupon_desc {
	char magic[4]; /* 0x00: "PCKC" */
	uint8_t fmt_major; /* 0x04: format major version (1): a reader refuses any other */
	uint8_t fmt_minor; /* 0x05: format minor version (0): a reader accepts a newer one */
	uint16_t length; /* 0x06: bytes in the descriptor, CRC included (256) */
	uint8_t coupon_type; /* 0x08: enum coupon_type */
	uint8_t coupon_rev; /* 0x09: board revision, ASCII 'A'-'Z' */
	uint8_t size_class; /* 0x0A: enum coupon_size */
	uint8_t default_slot; /* 0x0B: the slot it is designed for, 1-5 (SPEC §2) */
	uint8_t slot_mask; /* 0x0C: bit n-1 set: the coupon may be used in slot n */
	uint8_t flags; /* 0x0D: COUPON_FLAG_* bits */
	uint16_t needs; /* 0x0E: COUPON_NEEDS_* bits: slot features beyond the common pinout */
	uint32_t serial; /* 0x10: serial number of this coupon (0 = not assigned) */
	uint32_t date; /* 0x14: the descriptor's date, yyyymmdd as a decimal number (the JSON's, or make_eeprom.py --today) */
	uint8_t git_hash[8]; /* 0x18: first 8 bytes of the git commit of the board's generated files */
	uint32_t uses; /* 0x20: COUPON_USES_* bits: the slot pins the coupon connects */
	uint16_t spi_max_khz; /* 0x24: highest SPI clock all of its SPI devices accept, kHz (0: no SPI) */
	uint16_t i2c_max_khz; /* 0x26: highest I2C clock its I2C devices accept, kHz (the descriptor EEPROM: 400) */
	uint8_t select_scheme; /* 0x28: enum coupon_select: how the G-lines pick the site a lane reads */
	uint8_t select_steps; /* 0x29: select steps per scan frame (0: none) */
	uint16_t select_settle_ns; /* 0x2A: time from a select change to a settled lane, ns, coupon side only */
	uint32_t reserved0; /* 0x2C: 0 */
	struct coupon_desc_rail rails[2]; /* 0x30: [0] +3V3, [1] +5V */
	struct coupon_desc_lane lanes[4]; /* 0x40: AN0-AN3 */
	struct coupon_desc_gline glines[6]; /* 0x80: G0-G5 */
	struct coupon_desc_cs cs[2]; /* 0x98: CS0_N, CS1_N */
	struct coupon_desc_device devices[7]; /* 0xA0: up to 7 devices */
	uint8_t ext_format; /* 0xD8: enum coupon_ext: what ext[] holds */
	uint8_t ext_flags; /* 0xD9: COUPON_EXT_F_* bits */
	uint16_t ext_reserved; /* 0xDA: 0 */
	uint8_t ext[32]; /* 0xDC: type-specific block (reference ratios, site map) */
	uint32_t crc32; /* 0xFC: CRC-32/IEEE of bytes 0x00-0xFB */
} __attribute__((packed));
_Static_assert(sizeof(struct coupon_desc) == 256, "coupon_desc size");
_Static_assert(offsetof(struct coupon_desc, magic) == 0x00, "coupon_desc.magic");
_Static_assert(offsetof(struct coupon_desc, fmt_major) == 0x04, "coupon_desc.fmt_major");
_Static_assert(offsetof(struct coupon_desc, fmt_minor) == 0x05, "coupon_desc.fmt_minor");
_Static_assert(offsetof(struct coupon_desc, length) == 0x06, "coupon_desc.length");
_Static_assert(offsetof(struct coupon_desc, coupon_type) == 0x08, "coupon_desc.coupon_type");
_Static_assert(offsetof(struct coupon_desc, coupon_rev) == 0x09, "coupon_desc.coupon_rev");
_Static_assert(offsetof(struct coupon_desc, size_class) == 0x0A, "coupon_desc.size_class");
_Static_assert(offsetof(struct coupon_desc, default_slot) == 0x0B, "coupon_desc.default_slot");
_Static_assert(offsetof(struct coupon_desc, slot_mask) == 0x0C, "coupon_desc.slot_mask");
_Static_assert(offsetof(struct coupon_desc, flags) == 0x0D, "coupon_desc.flags");
_Static_assert(offsetof(struct coupon_desc, needs) == 0x0E, "coupon_desc.needs");
_Static_assert(offsetof(struct coupon_desc, serial) == 0x10, "coupon_desc.serial");
_Static_assert(offsetof(struct coupon_desc, date) == 0x14, "coupon_desc.date");
_Static_assert(offsetof(struct coupon_desc, git_hash) == 0x18, "coupon_desc.git_hash");
_Static_assert(offsetof(struct coupon_desc, uses) == 0x20, "coupon_desc.uses");
_Static_assert(offsetof(struct coupon_desc, spi_max_khz) == 0x24, "coupon_desc.spi_max_khz");
_Static_assert(offsetof(struct coupon_desc, i2c_max_khz) == 0x26, "coupon_desc.i2c_max_khz");
_Static_assert(offsetof(struct coupon_desc, select_scheme) == 0x28, "coupon_desc.select_scheme");
_Static_assert(offsetof(struct coupon_desc, select_steps) == 0x29, "coupon_desc.select_steps");
_Static_assert(offsetof(struct coupon_desc, select_settle_ns) == 0x2A, "coupon_desc.select_settle_ns");
_Static_assert(offsetof(struct coupon_desc, reserved0) == 0x2C, "coupon_desc.reserved0");
_Static_assert(offsetof(struct coupon_desc, rails) == 0x30, "coupon_desc.rails");
_Static_assert(offsetof(struct coupon_desc, lanes) == 0x40, "coupon_desc.lanes");
_Static_assert(offsetof(struct coupon_desc, glines) == 0x80, "coupon_desc.glines");
_Static_assert(offsetof(struct coupon_desc, cs) == 0x98, "coupon_desc.cs");
_Static_assert(offsetof(struct coupon_desc, devices) == 0xA0, "coupon_desc.devices");
_Static_assert(offsetof(struct coupon_desc, ext_format) == 0xD8, "coupon_desc.ext_format");
_Static_assert(offsetof(struct coupon_desc, ext_flags) == 0xD9, "coupon_desc.ext_flags");
_Static_assert(offsetof(struct coupon_desc, ext_reserved) == 0xDA, "coupon_desc.ext_reserved");
_Static_assert(offsetof(struct coupon_desc, ext) == 0xDC, "coupon_desc.ext");
_Static_assert(offsetof(struct coupon_desc, crc32) == 0xFC, "coupon_desc.crc32");

/* coupon_desc_validate() results */
enum coupon_desc_status {
	COUPON_DESC_OK = 0,
	COUPON_DESC_E_SIZE = -1,    /* fewer than COUPON_DESC_SIZE bytes */
	COUPON_DESC_E_BLANK = -2,   /* all 0xFF: an unwritten EEPROM */
	COUPON_DESC_E_MAGIC = -3,   /* not a coupon descriptor */
	COUPON_DESC_E_VERSION = -4, /* another major format version */
	COUPON_DESC_E_LENGTH = -5,  /* length field is not COUPON_DESC_SIZE */
	COUPON_DESC_E_CRC = -6,     /* CRC mismatch */
};

/* CRC-32/IEEE. On Zephyr v4.5.0 it is crc32_ieee() of <zephyr/sys/crc.h>, which needs CONFIG_CRC=y
 * (subsys/crc). Elsewhere, link an implementation with the same definition (zlib's crc32). */
#ifdef __ZEPHYR__
#include <zephyr/sys/crc.h>
#else
uint32_t crc32_ieee(const uint8_t *data, size_t len);
#endif

static inline uint16_t coupon_desc_le16(const uint8_t *p)
{
	return (uint16_t)(p[0] | (p[1] << 8));
}

static inline uint32_t coupon_desc_le32(const uint8_t *p)
{
	return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

/* The checks a reader makes before it trusts any field, in this order (DESCRIPTOR.md, "Reading"). */
static inline int coupon_desc_validate(const uint8_t *buf, size_t len)
{
	size_t i;
	uint16_t length;

	if (len < COUPON_DESC_SIZE) {
		return COUPON_DESC_E_SIZE;
	}
	for (i = 0; i < COUPON_DESC_SIZE && buf[i] == 0xFFu; i++) {
	}
	if (i == COUPON_DESC_SIZE) {
		return COUPON_DESC_E_BLANK;
	}
	if (buf[0] != 'P' || buf[1] != 'C' || buf[2] != 'K' || buf[3] != 'C') {
		return COUPON_DESC_E_MAGIC;
	}
	if (buf[4] != COUPON_DESC_FMT_MAJOR) {
		return COUPON_DESC_E_VERSION;
	}
	length = coupon_desc_le16(&buf[6]);
	if (length != COUPON_DESC_SIZE) {
		return COUPON_DESC_E_LENGTH;
	}
	if (crc32_ieee(buf, length - 4u) != coupon_desc_le32(&buf[length - 4u])) {
		return COUPON_DESC_E_CRC;
	}
	return COUPON_DESC_OK;
}

